import{_ as t,o,c as r,a2 as a}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"External Models","description":"","frontmatter":{},"headers":[],"relativePath":"development/admin/external_models.md","filePath":"versions/development/admin/external_models.md","lastUpdated":1795294041000}'),s={name:"development/admin/external_models.md"};function n(l,e,i,d,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="external-models" tabindex="-1">External Models <a class="header-anchor" href="#external-models" aria-label="Permalink to &quot;External Models&quot;">​</a></h1><p>The <strong>External Models</strong> admin page connects centrally managed model providers to prokube. Administrators can add provider credentials once, register models from those providers, and grant specific workspaces access to specific models.</p><p>Use this workflow when you need to:</p><ul><li>offer Mistral AI, Azure OpenAI, or a custom OpenAI-compatible endpoint;</li><li>share a centrally managed provider credential without copying it into workspace Secrets;</li><li>control which workspaces can use each external model.</li></ul><p>For OpenAI, Anthropic, or Gemini, workspace users can instead create their own Model Configuration backed by a workspace Kubernetes Secret. See <a href="./../agentops/agents.html#_2-choose-or-create-a-model-configuration">Agents</a>.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/external-models/external-models-provider-catalog-framed.png" alt="External Models page with the provider catalog for Anthropic, OpenAI, Mistral AI, Azure OpenAI, and custom OpenAI-compatible endpoints" loading="lazy"></p><p>Usage across all models and model pricing are on <a href="./llm_usage.html">LLM Usage and Cost</a>.</p><h2 id="provider-options" tabindex="-1">Provider Options <a class="header-anchor" href="#provider-options" aria-label="Permalink to &quot;Provider Options&quot;">​</a></h2><p>The admin-managed provider catalog supports:</p><ul><li>Anthropic;</li><li>OpenAI;</li><li>Mistral AI;</li><li>Azure OpenAI;</li><li>custom OpenAI-compatible endpoints.</li></ul><p>Anthropic uses its native protocol. The other provider types use an OpenAI-compatible protocol. Custom and Azure OpenAI providers require an upstream host; the path prefix selects the API path on that host.</p><h2 id="connect-a-provider" tabindex="-1">Connect a Provider <a class="header-anchor" href="#connect-a-provider" aria-label="Permalink to &quot;Connect a Provider&quot;">​</a></h2><p>Open <strong>External Models</strong> under <strong>Admin</strong>, then select <strong>Add Provider</strong>. Configure:</p><ul><li><strong>Provider</strong>: select an entry from the provider catalog.</li><li><strong>Provider name</strong>: unique name for the provider connection.</li><li><strong>Provider API key</strong>: credential stored centrally by prokube.</li><li><strong>Upstream host</strong> and <strong>Path prefix</strong>: configure the endpoint for custom and Azure OpenAI providers. The host is required; Azure defaults to <code>/openai/v1</code> for the path prefix.</li><li><strong>Models</strong>: discover model IDs or add them manually. Add at least one model before saving.</li></ul><p>Provider API keys are write-only. To rotate one later, edit the provider and enter a <strong>Replacement API key</strong>.</p><h3 id="azure-openai" tabindex="-1">Azure OpenAI <a class="header-anchor" href="#azure-openai" aria-label="Permalink to &quot;Azure OpenAI&quot;">​</a></h3><p>Enter your Azure resource host in <strong>Upstream host</strong>. <strong>Path prefix</strong> defaults to <code>/openai/v1</code>. Authentication uses the resource API key.</p><p>Only the Azure OpenAI v1 API is supported. Classic deployment URLs with an <code>api-version</code> parameter and Microsoft Entra ID sign-in aren&#39;t supported.</p><p>Add models manually using <strong>Deployment name</strong>: enter the deployment name from your Azure resource, not the underlying model ID. Discovery cannot enumerate deployment names.</p><h3 id="custom-endpoint-discovery-and-testing" tabindex="-1">Custom Endpoint Discovery and Testing <a class="header-anchor" href="#custom-endpoint-discovery-and-testing" aria-label="Permalink to &quot;Custom Endpoint Discovery and Testing&quot;">​</a></h3><p>For <strong>Custom OpenAI-compatible</strong>, <strong>Discover models</strong> requires HTTPS and a public DNS host. <strong>Test model access</strong> also permits private DNS hosts explicitly allowed by the platform administrator. Neither supports raw IP addresses, localhost, HTTP endpoints, or cluster-internal hosts.</p><p><strong>Test model access</strong> sends a minimal request for one chosen model and capability, which may incur a provider charge. It doesn&#39;t test every selected model or evaluate output quality.</p><p>For an endpoint that cannot be tested, add model IDs manually. Select <strong>Add Provider</strong>, review the warning, then explicitly select <strong>Add without successful test</strong>. This saves the provider without verifying runtime connectivity or model access. Discovery alone doesn&#39;t verify model access either.</p><h2 id="add-models" tabindex="-1">Add Models <a class="header-anchor" href="#add-models" aria-label="Permalink to &quot;Add Models&quot;">​</a></h2><p>Open a provider and switch to its <strong>Models</strong> tab. Models can be added in two ways:</p><ul><li><strong>Discover models</strong> queries the provider and lets you select one or more returned model IDs.</li><li><strong>Add manually</strong> registers a model ID directly.</li></ul><p>The main <strong>Models</strong> table shows each model&#39;s provider, API protocol, workspace-access count, and base URL. A model cannot be deleted while a workspace grant still references it, including an orphaned grant. When deletion is blocked, the dialog lists each blocking workspace, ModelConfig, and grant health. Select <strong>Open Workspace Access to revoke these grants</strong>, revoke the listed grants, then retry deletion.</p><h2 id="grant-workspace-access" tabindex="-1">Grant Workspace Access <a class="header-anchor" href="#grant-workspace-access" aria-label="Permalink to &quot;Grant Workspace Access&quot;">​</a></h2><p>Select <strong>Grant Workspace Access</strong>, then choose:</p><ul><li><strong>Workspace</strong>: the workspace that should receive the model.</li><li><strong>Route ID / ModelConfig name</strong>: the name shown in that workspace&#39;s Model Configurations.</li><li><strong>Resource</strong>: the provider model to grant.</li></ul><p>The grant creates a Model Configuration in the target workspace. It appears automatically on the workspace&#39;s <strong>Agents</strong> page with the source <strong>External model grant</strong>. Users can select it when creating an agent without creating their own provider Secret.</p><p>Agents reach every granted model through Agent Gateway&#39;s OpenAI-compatible API, so the Model Configuration&#39;s <strong>Protocol</strong> shows <strong>OpenAI-compatible</strong> even for an Anthropic model.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/external-models/external-models-workspace-access-view-traffic-framed.png" alt="Workspace Access table with a healthy grant and its View Traffic and Revoke Access actions" loading="lazy"></p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/external-models/agents-model-configurations-external-grant-framed.png" alt="Granted external model listed under Model Configurations with the source External model grant" loading="lazy"></p><p>The central provider credential is not exposed to the workspace. Revoke the grant from <strong>Workspace Access</strong> when the workspace should no longer use the model.</p><h3 id="grant-health-and-status" tabindex="-1">Grant Health and Status <a class="header-anchor" href="#grant-health-and-status" aria-label="Permalink to &quot;Grant Health and Status&quot;">​</a></h3><p>Each grant in <strong>Workspace Access</strong> shows the health of its resources, with a short explanation. An <strong>Orphaned</strong> grant has lost its workspace Model Configuration but still blocks model deletion; revoke it to remove it. Grants with <strong>Orphaned</strong> or <strong>Unknown</strong> health can be revoked directly.</p><p>A grant or revoke operation has its own status, separate from health. The page shows <strong>Applying</strong> for a few seconds while the Agent Gateway controller updates the workspace. Treat access as changed only once it shows <strong>Applied</strong>.</p><p>If the operation does not reach <strong>Applied</strong>:</p><ul><li><strong>Failed</strong>: resolve the blockers shown, then select <strong>Check again</strong>. If <strong>Check again</strong> isn&#39;t offered, the request wasn&#39;t accepted; review the details and try again.</li><li><strong>Unknown</strong> or <strong>Needs review</strong>: the change may or may not have been applied, and it is not sent again automatically. Select <strong>Check again</strong> if it is offered; it re-reads the status without repeating the change. Otherwise, select <strong>Review latest access</strong>, check the refreshed <strong>Workspace Access</strong> table, then select <strong>Acknowledge and continue</strong> before making another change.</li></ul><p>Grants of a deleted workspace stay listed until you revoke them. The revoke succeeds once Kubernetes has removed the workspace&#39;s resources; retry it if it is rejected before then.</p><p>Agents in the workspace use the granted model through its generated Model Configuration. External clients can call it through Agent Gateway at <code>/svc/ai/&lt;workspace&gt;/models/&lt;route-id&gt;/v1/...</code>, using the route ID chosen in the grant.</p><p>Granted models are not listed as individual services on the <strong>API Keys</strong> page. An external client needs a Bearer-format key with <strong>All external AI models</strong>, <strong>All AI models</strong>, or <strong>Full workspace access</strong>, which covers every granted model in the workspace. A key cannot be limited to one granted model. See <a href="./../platform/api_keys.html#create-a-key">API Keys</a>.</p><h3 id="traffic-for-a-grant" tabindex="-1">Traffic for a Grant <a class="header-anchor" href="#traffic-for-a-grant" aria-label="Permalink to &quot;Traffic for a Grant&quot;">​</a></h3><p>Use <strong>View Traffic</strong> in a grant&#39;s row menu to see how much the workspace uses the granted model, which sources call it, and what it costs. The same view appears on the granted Model Configuration&#39;s detail page under <strong>Agents</strong>.</p><p>Traffic is shown only to members of the workspace. For a workspace you don&#39;t belong to, <strong>View Traffic</strong> is disabled; use <a href="./llm_usage.html">LLM Usage and Cost</a> for platform-wide numbers instead.</p><h2 id="external-model-usage" tabindex="-1">External Model Usage <a class="header-anchor" href="#external-model-usage" aria-label="Permalink to &quot;External Model Usage&quot;">​</a></h2><p>The <strong>External model usage</strong> card shows LLM calls to the configured external providers, both through workspace grants and directly. Select <strong>Last hour</strong>, <strong>Last 24 hours</strong> (default), <strong>Last 7 days</strong>, or <strong>Max (N days)</strong>.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/external-models/external-models-usage-card-framed.png" alt="External model usage card with totals, trend, and breakdowns by source, provider, gateway model, and workspace" loading="lazy"></p><p>The card counts only routes whose backends are currently configured external providers. Self-hosted models are excluded even if they share a provider type or model name, and calls to a provider that has since been removed no longer appear here. Use <strong>LLM Usage and Cost — all models</strong> for all LLM calls, including self-hosted models and removed providers, and <strong>Set prices</strong> to open <a href="./llm_usage.html#model-pricing">Model Pricing</a>.</p><p>Costs are estimated at the prices that were set when each call was made. A model without a price shows tokens but no cost.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./llm_usage.html">LLM Usage and Cost</a></li><li><a href="./../agentops/agents.html">Agents</a></li><li><a href="./../agentops/agent_gateway.html">Agent Gateway</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../agentops/llm_serving.html">LLM Serving</a></li></ul>',53)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
